#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-19

# ============================================================================
# strip-skill-triggers.awk unit tests (#4147)
# ============================================================================
# Feeds fixture SKILL.md streams through scripts/lib/strip-skill-triggers.awk
# and asserts the triggers block is removed inside the frontmatter fence and
# nowhere else. The supported input shapes are pinned here so a future edit
# cannot silently stop stripping (Devin's loader drops the skill) or start
# eating body content.
#
# Test Count: 8
# ============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "${SCRIPT_DIR}/../.." && pwd)"
AWK_FILE="${PROJECT_ROOT}/scripts/lib/strip-skill-triggers.awk"

RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'

TESTS_PASSED=0
TESTS_FAILED=0

log_pass() { echo -e "  ${GREEN}✓${NC} $1"; TESTS_PASSED=$((TESTS_PASSED + 1)); }
log_fail() { echo -e "  ${RED}✗${NC} $1"; TESTS_FAILED=$((TESTS_FAILED + 1)); }

WORK="$(mktemp -d "${TMPDIR:-/tmp}/ork-strip-triggers.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

echo "═══════════════════════════════════════════════════════════════"
echo "  strip-skill-triggers.awk: fixture tests"
echo "═══════════════════════════════════════════════════════════════"

# assert_transform <name> <input-file> <expected-file>
assert_transform() {
    local name="$1" in="$2" want="$3" out="$WORK/out.txt"
    if awk -f "$AWK_FILE" "$in" > "$out" && diff -u "$want" "$out" > "$WORK/diff.txt" 2>&1; then
        log_pass "$name"
    else
        log_fail "$name"
        sed 's/^/      /' "$WORK/diff.txt" | head -15
    fi
}

# 1. Indented block children are dropped.
cat > "$WORK/in1.md" <<'EOF'
---
name: auto
triggers:
  keywords: [a, b]
  examples:
    - "review this"
description: x
---
body
EOF
cat > "$WORK/want1.md" <<'EOF'
---
name: auto
description: x
---
body
EOF
assert_transform "indented children dropped" "$WORK/in1.md" "$WORK/want1.md"

# 2. A blank line inside the block does not leak orphaned keys.
cat > "$WORK/in2.md" <<'EOF'
---
triggers:
  keywords: [a]

  anti-triggers: [x]
next: 1
---
EOF
cat > "$WORK/want2.md" <<'EOF'
---
next: 1
---
EOF
assert_transform "blank line inside block dropped" "$WORK/in2.md" "$WORK/want2.md"

# 3. Zero-indent sequence items are still children.
cat > "$WORK/in3.md" <<'EOF'
---
triggers:
- a
- b
next: 1
---
EOF
cat > "$WORK/want3.md" <<'EOF'
---
next: 1
---
EOF
assert_transform "zero-indent sequence items dropped" "$WORK/in3.md" "$WORK/want3.md"

# 4. CRLF fences still bound the frontmatter region.
printf -- '---\r\ntriggers:\r\n  keywords: [a]\r\nnext: 1\r\n---\r\nbody\r\n' > "$WORK/in4.md"
printf -- '---\r\nnext: 1\r\n---\r\nbody\r\n' > "$WORK/want4.md"
assert_transform "CRLF fences bound the region" "$WORK/in4.md" "$WORK/want4.md"

# 5. triggers as the last frontmatter key: the closing fence survives.
cat > "$WORK/in5.md" <<'EOF'
---
name: auto
triggers:
  keywords: [a]
---
body
EOF
cat > "$WORK/want5.md" <<'EOF'
---
name: auto
---
body
EOF
assert_transform "closing fence survives last-key block" "$WORK/in5.md" "$WORK/want5.md"

# 6. A col-0 triggers: line in the body is body text, not frontmatter.
cat > "$WORK/in6.md" <<'EOF'
---
name: auto
---
triggers:
  not frontmatter
EOF
cat > "$WORK/want6.md" <<'EOF'
---
name: auto
---
triggers:
  not frontmatter
EOF
assert_transform "body triggers: text preserved" "$WORK/in6.md" "$WORK/want6.md"

# 7. Look-alike keys are untouched: x-triggers and nested metadata.triggers.
cat > "$WORK/in7.md" <<'EOF'
---
x-triggers: keep
metadata:
  triggers: nested
---
EOF
cp "$WORK/in7.md" "$WORK/want7.md"
assert_transform "x-triggers and nested triggers preserved" "$WORK/in7.md" "$WORK/want7.md"

# 8. Inline scalar form triggers: {} is dropped with the key line.
cat > "$WORK/in8.md" <<'EOF'
---
triggers: {}
next: 1
---
EOF
cat > "$WORK/want8.md" <<'EOF'
---
next: 1
---
EOF
assert_transform "inline triggers: {} dropped" "$WORK/in8.md" "$WORK/want8.md"

echo ""
echo "Passed: $TESTS_PASSED  Failed: $TESTS_FAILED"
[[ $TESTS_FAILED -gt 0 ]] && exit 1
exit 0
